import {DATA, shuffle, staff, diagram, makeOptions, describe} from './game-core.mjs';
import {initTheme} from './theme.mjs';

let instrument=null,order=[],index=0,phase=0,score=0,locked=false,results=[];
const app=document.getElementById('app');

function startScreen(){app.innerHTML=`<section class="panel start"><div class="eyebrow">8 notes · 2 questions each</div><h1>Know your stuff? Prove it!!</h1><p>Choose your instrument. Read the note on the staff, then pick the picture showing how to play it. Each correct answer earns one point.</p><div class="instrument-grid">${Object.entries(DATA).map(([id,d])=>`<button class="instrument" data-id="${id}" aria-pressed="false">${d.label}</button>`).join('')}</div><button class="primary" id="start" disabled>Start game</button></section>`;document.querySelectorAll('.instrument').forEach(b=>b.onclick=()=>{instrument=b.dataset.id;document.querySelectorAll('.instrument').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b?'true':'false')});document.getElementById('start').disabled=false});document.getElementById('start').onclick=()=>{order=shuffle([0,1,2,3,4,5,6,7]);index=0;phase=0;score=0;locked=false;results=Array.from({length:8},()=>[false,false]);render()}}

function render(){let d=DATA[instrument],n=order[index],o=makeOptions(d,n,phase),isName=phase===0;app.innerHTML=`<section class="panel"><div class="topline"><div><div class="eyebrow">${d.label} · Note ${index+1} of 8</div><div class="small-note">${isName?'Part 1 · Name the note':'Part 2 · How do you play it?'}</div></div><strong>${score} / 16 points</strong></div><div class="meter" role="progressbar" aria-valuenow="${index*2+phase}" aria-valuemin="0" aria-valuemax="16" aria-label="Questions completed"><div style="width:${(index*2+phase)/16*100}%"></div></div><div class="play-layout"><div><div class="staff-card">${staff(d.notes[n],d.clef)}</div><p class="small-note">${d.clef==='bass'?'Bass':'Treble'} clef · ${instrument==='clarinet'?'C major note names · below the break':instrument==='alto'?'G major written scale':instrument==='trumpet'?'C major written scale':'B♭ major written scale'}</p></div><div class="question"><div class="eyebrow">${isName?'Read':'Play'}</div><h2>${isName?'What is the letter name of this note?':d.kind==='mallet'?'Which bar plays this note?':d.kind==='slide'?'Which slide position plays this note?':'Which picture shows the correct fingering?'}</h2><div class="choices ${!isName&&d.kind==='mallet'?'keyboard-choices':''}" id="choices">${o.arr.map((v,i)=>`<button class="choice ${isName?'':`diagram-choice ${d===DATA.clarinet||d===DATA.alto?'vertical':d.kind==='mallet'?'keyboard':''}`}" data-answer="${i}" aria-label="${isName?v:d.kind==='mallet'?`Keyboard choice ${i+1}`:describe(d,v)}">${isName?v:diagram(d,v)}${isName||d.kind==='mallet'?'':`<div class="diagram-caption">${describe(d,v)}</div>`}</button>`).join('')}</div><div id="feedback" class="feedback" role="status" aria-live="polite"></div><button class="primary footer-action" id="next" hidden>${phase===0?'Next: fingering':'Next note'}</button></div></div></section>`;document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>{if(locked)return;locked=true;let v=o.arr[+b.dataset.answer],good=v===o.correct;results[index][phase]=good;if(good)score++;b.classList.add(good?'correct':'wrong');document.querySelectorAll('.choice').forEach(x=>{x.disabled=true;if(o.arr[+x.dataset.answer]===o.correct)x.classList.add('correct')});let feedback=document.getElementById('feedback');feedback.className='feedback '+(good?'good':'bad');feedback.textContent=good?'Correct! +1 point':!isName&&d.kind==='mallet'?'The correct keyboard is highlighted.':`The correct answer is ${isName?o.correct:describe(d,o.correct)}.`;let next=document.getElementById('next');next.hidden=false;next.textContent=phase===0?'Next: fingering':index===7?'See results':'Next note';next.focus()});document.getElementById('next').onclick=()=>{locked=false;if(phase===0)phase=1;else{phase=0;index++}if(index>=8)finish();else render()}}

function finish(){let d=DATA[instrument];app.innerHTML=`<section class="panel finish"><div class="eyebrow">Scale complete · ${d.label}</div><h1>Nice work!</h1><div class="score">${score} / 16</div><p>One point for each note name and one for each playing choice.</p><div class="review">${order.map((v,i)=>`<div>${d.notes[v]}<br><span aria-label="Note name ${results[i][0]?'correct':'incorrect'}, playing choice ${results[i][1]?'correct':'incorrect'}">Name ${results[i][0]?'✓':'✕'} · Play ${results[i][1]?'✓':'✕'}</span></div>`).join('')}</div><button class="primary" id="again">Play again</button><p class="reference">Fingerings use common standard choices; some instruments have alternate fingerings. Check your band method book for the version your class uses.</p></section>`;document.getElementById('again').onclick=startScreen}

initTheme();startScreen();document.getElementById('home').addEventListener('click',startScreen);
